mapper.sql:
WHERE a.achievement_type = 'EMPLOYMENT_RATE_ACHIEVEMENT'
  AND a.deleted_yn = 'N'

    AND a.evaluation_year = #{q.evaluationYear}


    AND a.management_item_code = #{q.managementItemCode}


    AND a.achievement_status = #{q.achievementStatus}


    AND (
        FALSE

            OR a.teacher_user_id = #{q.userId}


            OR EXISTS (
                SELECT 1
                FROM organization_user_mappings rm
                JOIN organization_user_mappings tm ON tm.organization_code = rm.organization_code
                WHERE rm.user_id = #{q.userId}
                  AND rm.status = 'ACTIVE'
                  AND tm.status = 'ACTIVE'
                  AND tm.user_id = a.teacher_user_id
            )


            OR EXISTS (
                SELECT 1
                FROM evaluation_organization_mappings pm
                JOIN organization_user_mappings tm ON tm.organization_code = pm.organization_code
                WHERE pm.user_id = #{q.userId}
                  AND pm.business_type = 'FACULTY_ACHIEVEMENT'
                  AND pm.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL')
                  AND tm.status = 'ACTIVE'
                  AND tm.user_id = a.teacher_user_id
            )

    )

mapper.select:
SELECT 
FROM education_achievements a

ORDER BY a.achievement_date DESC, a.achievement_id DESC

    LIMIT #{q.pageSize}
    OFFSET #{q.rowOffset}

SELECT COUNT(*)
FROM education_achievements a
WHERE a.teacher_user_id = #{r.teacherUserId}
  AND a.evaluation_year = #{r.evaluationYear}
  AND a.achievement_type = 'EMPLOYMENT_RATE_ACHIEVEMENT'
  AND a.management_item_code = #{r.managementItemCode}
  AND a.achievement_date = #{r.achievementDate}
  AND a.deleted_yn = 'N'
AND a.achievement_id != #{r.achievementId}

mapper.insert:
INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name, before_value, after_value,
    changed_by, change_reason, request_id
)
VALUES (
    'education_achievements', CAST(#{r.achievementId} AS text), #{action}, #{field}, #{before}, #{after},
    #{r.actor}, '취업률 실적 저장', #{r.requestId}
)

INSERT INTO education_achievement_status_histories (
    achievement_type, achievement_id, next_status, action_type, opinion, processed_by, request_id
)
VALUES (
    'EMPLOYMENT_RATE_ACHIEVEMENT', #{r.achievementId}, 'DRAFT', 'CREATE',
    '취업률 실적 최초 입력', #{r.actor}, #{r.requestId}
)

INSERT INTO excel_upload_files (
    upload_id, business_type, template_id, file_token, original_file_name,
    validation_status, uploader_user_id, request_id, error_file_token
)
VALUES (
    #{r.uploadId}, 'EMPLOYMENT_RATE_ACHIEVEMENT', #{r.templateId}, #{r.fileToken}, #{r.fileName},
    #{r.validationStatus}, #{r.actor}, #{r.requestId}, #{r.errorFileToken}
)

INSERT INTO excel_upload_histories (
    upload_id, total_count, success_count, error_count, saved_count, processor_user_id,
    processing_time_millis, request_id
)
VALUES (
    #{r.uploadId}, #{r.totalCount}, #{r.successCount}, #{r.errorCount}, 0, #{r.actor},
    #{r.elapsed}, #{r.requestId}
)

mapper.update:
UPDATE excel_upload_files
SET validation_status = 'COMMITTED', request_id = #{requestId}
WHERE upload_id = #{id};
UPDATE excel_upload_histories
SET saved_count = #{count}, processed_at = CURRENT_TIMESTAMP, request_id = #{requestId}
WHERE upload_id = #{id}
